<script setup lang="ts">
import {useQuery} from '@tanstack/vue-query'
import type {KabanWorkspace} from '~~/shared/types/kaban'
const props=defineProps<{projectId?:string;attachmentHint?:string}>(),emit=defineEmits<{close:[];choose:[task:{taskId:string;boardId:string;title:string}]}>()
const auth=useAuthStore(),source=ref(props.projectId?`project:${props.projectId}`:'personal'),mode=ref<'attach'|'create'>('attach'),search=ref(''),title=ref(''),description=ref(''),dueOn=ref(''),category=ref(''),stage=ref(''),newCategory=ref('Задачи из чата'),participants=ref<string[]>([]),busy=ref(false),error=ref('')
const sources=useQuery({queryKey:computed(()=>['account',auth.user?.id,'chat-task-sources']),queryFn:()=>sharedRequest<{label:string;value:string}[]>('/api/chats/task-sources'),retry:false})
const workspace=useQuery({queryKey:computed(()=>['account',auth.user?.id,'chat-task-workspace',source.value]),queryFn:({signal})=>sharedRequest<KabanWorkspace>(source.value.startsWith('project:')?`/api/kaban?project=${source.value.slice(8)}`:`/api/kaban?vault=${source.value.startsWith('vault:')?source.value.slice(6):'personal'}`,{signal}),retry:false})
const categories=computed(()=>workspace.data.value?.categories.filter(category=>!category.archived)??[])
const stages=computed(()=>categories.value.find(item=>item.id===category.value)?.effectiveStages??categories.value.find(item=>item.id===category.value)?.stages??workspace.data.value?.board.defaultStages??workspace.data.value?.board.stages??[])
watch(()=>sources.data.value,items=>{if(items&&!items.some(item=>item.value===source.value))source.value='personal'})
watch(()=>workspace.data.value,data=>{category.value=data?.categories.find(item=>!item.archived)?.id??'';stage.value='';participants.value=[]})
watch(stages,items=>{if(!items.some(item=>item.id===stage.value))stage.value=items[0]?.id??''},{immediate:true})
const tasks=computed(()=>workspace.data.value?.tasks.filter(task=>!task.archived&&task.title.toLocaleLowerCase('ru').includes(search.value.toLocaleLowerCase('ru')))??[])
async function create(){const data=workspace.data.value;if(!data||!data.canEdit||busy.value)return;busy.value=true;error.value='';try{
 if(!category.value){const created=await sharedRequest<{id:string}>('/api/kaban/categories',{method:'POST',body:{boardId:data.board.id,revision:0,data:{name:newCategory.value.trim()||'Задачи из чата',parentId:null,color:'#8292a8'}}});category.value=created.id;const selected=category.value;await workspace.refetch();category.value=selected}
 const stageId=stages.value.some(item=>item.id===stage.value)?stage.value:stages.value[0]?.id;if(!stageId)throw new Error('На доске нет доступной стадии')
 const task=await sharedRequest<{id:string}>('/api/kaban/tasks',{method:'POST',body:{revision:0,boardId:data.board.id,stageId,categoryIds:[category.value],participantIds:participants.value,data:{title:title.value.trim(),description:description.value,dueOn:dueOn.value,todos:[]}}})
 emit('choose',{taskId:task.id,boardId:data.board.id,title:title.value.trim()});emit('close')
}catch(failure:any){error.value=failure?.data?.message||failure?.message||'Не удалось создать задачу'}finally{busy.value=false}}
</script>
<template><UModal :open="true" title="Задача Кабана" description="Выберите доступную задачу или создайте новую. Доступ к задаче определяется правами её доски." :dismissible="!busy" @update:open="value=>{if(!value)emit('close')}"><template #body><div class="chat-task-picker"><USelect v-model="source" :items="sources.data.value??[]" aria-label="Доска Кабана" :disabled="busy"/><div class="flex gap-2"><UButton label="Прикрепить задачу" color="neutral" :variant="mode==='attach'?'soft':'ghost'" @click="mode='attach'"/><UButton label="Создать задачу" color="neutral" :variant="mode==='create'?'soft':'ghost'" :disabled="!workspace.data.value?.canEdit" @click="mode='create'"/></div><UAlert v-if="error||workspace.error.value" color="error" :description="error||(workspace.error.value as any)?.data?.message||'Доска недоступна'"/><p v-if="workspace.isPending.value">Загружаем Кабан…</p><template v-else-if="mode==='attach'"><UInput v-model="search" icon="i-lucide-search" placeholder="Поиск задачи" aria-label="Поиск задачи"/><div class="chat-task-choices"><button v-for="task in tasks" :key="task.id" @click="emit('choose',{taskId:task.id,boardId:task.boardId,title:task.title});emit('close')"><UIcon name="i-lucide-columns-3"/><span>{{task.title}}<small>{{task.closedAt?'Завершена':'В работе'}}</small></span><UIcon name="i-lucide-plus"/></button><p v-if="!tasks.length">Доступных задач по этому запросу нет.</p></div></template><form v-else class="chat-task-picker" @submit.prevent="create"><UFormField label="Название задачи" required><UInput v-model="title" required :maxlength="200" class="w-full"/></UFormField><UFormField label="Описание"><UTextarea v-model="description" :maxlength="20000" class="w-full"/></UFormField><UFormField label="Срок"><UInput v-model="dueOn" type="date"/></UFormField><USelect v-if="categories.length" v-model="category" :items="categories.map(item=>({label:item.name,value:item.id}))" aria-label="Категория задачи"/><UFormField v-else label="Новая категория"><UInput v-model="newCategory" required :maxlength="60" class="w-full"/></UFormField><USelect v-model="stage" :items="stages.map(item=>({label:item.name,value:item.id}))" aria-label="Стадия задачи"/><fieldset class="chat-task-picker"><legend>Ответственные</legend><UCheckbox v-for="person in workspace.data.value?.people.filter(person=>workspace.data.value?.eligibleIds.includes(person.id))||[]" :key="person.id" :model-value="participants.includes(person.id)" :label="person.fullName||person.email" @update:model-value="value=>participants=value?[...new Set([...participants,person.id])]:participants.filter(id=>id!==person.id)"/></fieldset><p class="text-xs text-slate-400">{{props.attachmentHint||'После создания задача сохранится в Кабане. Отправьте сообщение, чтобы поделиться ей в беседе.'}}</p><UButton type="submit" label="Создать и прикрепить" :loading="busy" :disabled="!title.trim()"/></form></div></template></UModal></template>
<style scoped>.chat-task-picker{display:grid;gap:16px}.chat-task-choices{display:grid;gap:8px;max-height:50vh;overflow:auto}.chat-task-choices>button{display:flex;align-items:center;gap:10px;text-align:left;padding:12px;border:1px solid #e2e8f0;border-radius:10px;font-size:13px}.chat-task-choices>button>span{flex:1;overflow-wrap:anywhere}.chat-task-choices small{display:block;font-size:11px;color:#94a3b8;margin-top:4px}</style>
